SELECT a.root_type,g.account,a.account_name,SUM(g.debit-g.credit) AS balance FROM "tabGL Entry" g JOIN "tabAccount" a ON a.name=g.account WHERE (%(company)s='' OR g.company=%(company)s) AND (%(to_date)s='' OR g.posting_date<=%(to_date)s) AND a.root_type IN ('Asset','Liability','Equity') GROUP BY a.root_type,g.account,a.account_name ORDER BY CASE a.root_type WHEN 'Asset' THEN 1 WHEN 'Liability' THEN 2 ELSE 3 END,a.account_number
